            pence += missing * each;
        }
        if (line.kind === "lifejacket") {
            // A damaged lifejacket cannot be lent again, so it is charged in full.
            pence += line.damaged * each;
        } else {
            // Other damaged gear is charged at half its cost, each item rounded up to a whole penny.
            pence += line.damaged * Math.ceil(each / 2);
